INSERT INTO `diag_fault_event_dict` (`id`, `module_type`, `event_name`, `args1_desc`, `args2_desc`, `args3_desc`, `node_name`, `event_function`, `is_fault`, `common_params`, `fault_reason`, `fault_impact`, `remark`) VALUES
  (1, 'GPP', '200EXC', '0', 'PC值', 'LR值', 'GPP', '记录系统异常', 1, '参数2和参数3的值和异常位置有关，不固定，比如：参数2：0X10019FE4 参数3：0X1001A260', '某些处理器在配置中发生该异常时CPU停止运行，表现为机器死机，此时OS不能运行，故也可能不输出异常信息', '机器停止运行', ''),
  (2, 'GPP', '200EXC1', '0', 'PC值', 'LR值', 'GPP', '记录系统异常', 1, '参数2和参数3的值和异常位置有关，不固定，比如：参数2：0X10019FE4 参数3：0X1001A260', '某些处理器在配置中发生该异常时CPU停止运行，表现为机器死机，此时OS不能运行，故也可能不输出异常信息', '机器停止运行', ''),
  (3, 'GPP', '200PANICEXC', '0', 'PC值', 'LR值', 'GPP', '记录系统异常', 1, '参数2和参数3的值和异常位置有关，不固定，比如：参数2：0X10019FE4 参数3：0X1001A260', '某些处理器在配置中发生该异常时CPU停止运行，表现为机器死机，此时OS不能运行，故也可能不输出异常信息', '机器停止运行', ''),
  (4, 'GPP', '300PANICEXC', '0', 'PC值', 'LR值', 'GPP', '记录系统异常', 1, '参数2和参数3的值和异常位置有关，不固定，比如：参数2：0X10019FE4 参数3：0X1001A261', '数据的加载，存储，cache操作对硬件表的查询引起的页错误，默认有异常信息输出。', '未知错误', ''),
  (5, 'GPP', '400EXC', '0', 'PC值', 'LR值', 'GPP', '记录系统异常', 1, '参数2和参数3的值和异常位置有关，不固定，比如：参数2：0X10019FE4 参数3：0X1001A262', '取指令的地址不能访问;默认有异常信息输出', '未知错误', ''),
  (6, 'GPP', '400PANICEXC', '0', 'PC值', 'LR值', 'GPP', '记录系统异常', 1, '参数2和参数3的值和异常位置有关，不固定，比如：参数2：0X10019FE4 参数3：0X1001A262', '取指令的地址不能访问;默认有异常信息输出', '未知错误', ''),
  (7, 'GPP', '600EXC', '0', 'PC值', 'LR值', 'GPP', '记录系统异常', 1, '参数2和参数3的值和异常位置有关，不固定，比如：参数2：0X10019FE4 参数3：0X1001A263', '指令执行中的操作数不满足指令的对齐条件（如：双精度浮点操作指令的操作数地址没有8字节对齐等）;默认有异常信息输出', '未知错误', ''),
